WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT s.id, s.session_id, s.event_type, s.page, s.duration_sec, s.new_group_flag, s.session_no, (SELECT AVG(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS avg_web_event_duration_sec FROM islands s ORDER BY new_group_flag DESC
